function recordAssist(p){const latest=goals().slice().reverse().find(g=>!g.assistId);if(latest){assignAssist(latest.id,p);return}const gs=goals().filter(g=>!g.assistId);if(!gs.length){const all=goals();if(!all.length)return alert('Record a goal first.');openModal('Choose a goal to update',all.map(g=>`<button class="goalpick" data-assist-goal="${g.id}"><strong>${esc(g.at)} · ${esc(g.scorerName)}</strong><span class="muted">${esc(g.period)} · ${g.assistName?'Assist: '+esc(g.assistName):'No assist yet'}</span></button>`).join(''));pendingAssistPlayer=p;return}openModal('Which goal did '+p.name+' assist?',gs.map(g=>`<button class="goalpick" data-assist-goal="${g.id}"><strong>${esc(g.at)} · ${esc(g.scorerName)}</strong><span class="muted">${esc(g.period)} · ${esc(g.assistName||'No assist yet')}</span></button>`).join('')+`<p class="muted">Goals already assigned an assist are hidden. To change one, use Edit on the timeline.</p>`);pendingAssistPlayer=p}
