$('exportBtn').onclick=exportBackup;$('historyExport').onclick=exportBackup;if($('teamDataExportBtn'))$('teamDataExportBtn').onclick=exportTeamData;const openTeamImportPicker=()=>{const input=$('teamDataImportFile');if(!input)return;try{if(typeof input.showPicker==='function')input.showPicker();else input.click()}catch{input.click()}};if($('teamDataImportBtn'))$('teamDataImportBtn').onclick=openTeamImportPicker;if($('teamPageImportDataBtn'))$('teamPageImportDataBtn').onclick=openTeamImportPicker;if($('teamDataImportFile'))$('teamDataImportFile').onchange=async e=>{const file=e.target.files&&e.target.files[0];if(file)await importTeamDataFile(file);e.target.value=''};bindSimpleListBackup('exportOpponentsBtn','importOpponentsBtn','importOpponentsFile','clubs','opposition clubs');bindSimpleListBackup('exportKitsBtn','importKitsBtn','importKitsFile','kitColours','kit colours');$('importBtn').onclick=()=>$('importFile').click();if($('historyImport'))$('historyImport').onclick=()=>$('historyImportFile').click();if($('historyImportFile'))$('historyImportFile').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{let x=JSON.parse(await f.text());if(!Array.isArray(x.squad)||!x.match||!Array.isArray(x.matches))throw Error('invalid');if(confirm('Import backup and replace all data currently on this device? Export your current data first if you want to keep it.')){data=x;save();alert('Backup restored successfully.')}}catch{alert('Could not import this file. Choose a Touchline Tracker JSON backup.')}e.target.value=''};
$('importFile').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{let x=JSON.parse(await f.text());if(!Array.isArray(x.squad)||!x.match||!Array.isArray(x.matches))throw Error('invalid');if(confirm('Import backup and replace all data currently on this device? Export your current data first if you want to keep it.')){data=x;save();alert('Backup restored successfully.')}}catch{alert('Could not import this file. Choose a Touchline Tracker JSON backup.')}e.target.value=''};
$('saveSettingsBtn').onclick=()=>{document.querySelectorAll('[data-setting-label]').forEach(i=>{data.settings.eventNames[i.dataset.settingLabel]=i.value.trim()||i.dataset.settingLabel});let order=[...document.querySelectorAll('[data-setting-order]')].map(i=>({key:i.dataset.settingOrder,n:Number(i.value)})).filter(x=>x.n>0).sort((a,b)=>a.n-b.n).map(x=>x.key);if(order.length)data.settings.buttonOrder=order;save();alert('Button settings saved.')};
$('addCustomEventBtn').onclick=()=>{let label=prompt('Name of additional event, e.g. Offside');if(!label||!label.trim())return;let key='custom_'+label.trim().toLowerCase().replace(/[^a-z0-9]+/g,'_');data.settings.extraEvents=data.settings.extraEvents||[];if(!data.settings.extraEvents.some(x=>x.key===key))data.settings.extraEvents.push({key,label:label.trim()});save()};
$('deleteCurrentBtn').onclick=()=>{if(!confirm('Permanently delete the current match data? This cannot be undone.'))return;let team=m().team;data.match=freshMatch(team);save();setTab('live')};
function safeDate(){let d=new Date(),local=new Date(d.getTime()-d.getTimezoneOffset()*60000);return local.toISOString().slice(0,10)}
setInterval(()=>{if($('clock'))$('clock').textContent=stamp();if($('periodClock'))$('periodClock').textContent=periodStamp();if($('bottomClock'))$('bottomClock').textContent=stamp();if($('bottomPeriodClock'))$('bottomPeriodClock').textContent=periodStamp();if($('bottomPeriodLabel'))$('bottomPeriodLabel').textContent=m().period==='Not started'?'Not started':m().period==='Full time'?'Full time':m().period},500);
if('serviceWorker' in navigator && location.protocol!=='file:'){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}))}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;$('installNotice').innerHTML='This app can be installed on your device. <button class="primary small" id="installBtn">Install app</button>';setTimeout(()=>{let b=$('installBtn');if(b)b.onclick=async()=>{deferredPrompt.prompt();await deferredPrompt.userChoice;deferredPrompt=null}},0)});
bindVersionDiagnostics();
