openAppDB().then(async db=>{if(!db||resetInProgress)return;const idb=await idbGet();if(resetInProgress)return;if(idb){const localCount=Array.isArray(data?.matches)?data.matches.length:0,idbCount=Array.isArray(idb.matches)?idb.matches.length:0;const localStamp=Date.parse(data?.storageUpdatedAt||0)||0,idbStamp=Date.parse(idb.storageUpdatedAt||0)||0;if(!localStorage.getItem(KEY)||idbCount>localCount||(idbCount===localCount&&idbStamp>localStamp)){data=idb;if(!Array.isArray(data.matches))data.matches=[];if(!data.settings)data.settings={};try{localStorage.setItem(KEY,JSON.stringify(data))}catch{}render();return}}if(data)idbPut(JSON.parse(JSON.stringify(data)));}).catch(err=>console.warn('Storage reconciliation failed',err));

